package com.bank.settle;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class TotallerDemo {
    private static final Logger log = Logger.getLogger("Totaller");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // 100,000 amounts of 10.00 each → exact expected total 1,000,000.00
        List<BigDecimal> amounts = IntStream.range(0, 100_000)
            .mapToObj(i -> new BigDecimal("10.00"))
            .collect(Collectors.toList());
        SettlementTotaller totaller = new SettlementTotaller();

        BigDecimal safe = totaller.parallelTotal(amounts);
        log.info(() -> "Safe parallel reduce total: " + safe); // 1000000.00 every run
    }
}

// ─── Would be in service/SettlementTotaller.java ───
class SettlementTotaller {
    // SAFE: associative, stateless reduce — identity ZERO, add accumulator + combiner
    BigDecimal parallelTotal(List<BigDecimal> amounts) {
        return amounts.parallelStream()
            .reduce(BigDecimal.ZERO, BigDecimal::add, BigDecimal::add);
    }

    // UNSAFE — shown ONLY to explain the data race; never use this.
    // BigDecimal[] total = { BigDecimal.ZERO };
    // amounts.parallelStream().forEach(a -> total[0] = total[0].add(a)); // RACE → wrong, non-deterministic
}
